{"command":"python3 -c "
import pandas as pd
df = pd.read_csv('outputs/t12_selected_matrix.csv')
print('Checking for commas or quotes in city_name:')
for col in df.columns:
    if df[col].apply(lambda x: ',' in str(x) if pd.notna(x) else False).any():
        print(f'{col} has commas')
    if df[col].apply(lambda x: '\"' in str(x) if pd.notna(x) else False).any():
        print(f'{col} has quotes')
""}

